/**
 * BinomialTab.jsx
 * Comprehensive Binomial Distribution Calculator and Visualizer
 *
 * Features:
 * - Interactive parameter input (n, p)
 * - Automatic calculation of derived statistics (q, mean, variance, std dev, skew)
 * - PDF and CDF calculations
 * - Discrete outcomes table with probabilities
 * - Interactive graphs for PDF and CDF
 * - Educational content on formulas and relationships
 */

import React, { useState, useEffect, useMemo } from 'react';
import { Calculator, BarChart3, Info, Table, TrendingUp } from 'lucide-react';
import { trackEvent } from '../../../utils/analytics';

const BinomialTab = () => {
  // Input parameters
  const [n, setN] = useState(10);
  const [p, setP] = useState(0.5);

  // Display options
  const [showFormulas, setShowFormulas] = useState(false);
  const [showAdvancedMath, setShowAdvancedMath] = useState(false);

  // Track component usage
  useEffect(() => {
    trackEvent('binomial_tab_loaded', { suite: 'probability' });
  }, []);

  // Calculate derived statistics
  const statistics = useMemo(() => {
    const q = 1 - p;
    const mean = n * p;
    const variance = n * p * q;
    const stdDev = Math.sqrt(variance);
    const skew = (q - p) / stdDev;

    return { q, mean, variance, stdDev, skew };
  }, [n, p]);

  // Binomial coefficient calculation (n choose k)
  const binomialCoeff = (n, k) => {
    if (k < 0 || k > n) return 0;
    if (k === 0 || k === n) return 1;

    let result = 1;
    for (let i = 1; i <= k; i++) {
      result = result * (n - i + 1) / i;
    }
    return result;
  };

  // PDF calculation
  const pdf = (k) => {
    return binomialCoeff(n, k) * Math.pow(p, k) * Math.pow(1 - p, n - k);
  };

  // CDF calculation
  const cdf = (k) => {
    let sum = 0;
    for (let i = 0; i <= k; i++) {
      sum += pdf(i);
    }
    return sum;
  };

  // Generate discrete outcomes table
  const outcomeTable = useMemo(() => {
    const table = [];
    for (let k = 0; k <= n; k++) {
      const probability = pdf(k);
      const cumulative = cdf(k);
      table.push({
        k,
        probability,
        cumulative,
        percentage: (probability * 100).toFixed(4),
        cumulativePercentage: (cumulative * 100).toFixed(4)
      });
    }
    return table;
  }, [n, p]);

  // Generate chart data for visualization
  const chartData = useMemo(() => {
    const pdfData = [];
    const cdfData = [];

    for (let k = 0; k <= n; k++) {
      pdfData.push({ x: k, y: pdf(k) });
      cdfData.push({ x: k, y: cdf(k) });
    }

    return { pdfData, cdfData };
  }, [n, p]);

  // Handle parameter changes with validation
  const handleNChange = (value) => {
    const newN = Math.max(1, Math.min(100, parseInt(value) || 1));
    setN(newN);
    trackEvent('binomial_parameter_change', { parameter: 'n', value: newN });
  };

  const handlePChange = (value) => {
    const newP = Math.max(0, Math.min(1, parseFloat(value) || 0));
    setP(newP);
    trackEvent('binomial_parameter_change', { parameter: 'p', value: newP });
  };

  // Simple SVG chart component for PDF
  const PDFChart = ({ data }) => {
    const maxY = Math.max(...data.map(d => d.y));
    const width = 400;
    const height = 200;
    const margin = { top: 20, right: 20, bottom: 40, left: 40 };
    const chartWidth = width - margin.left - margin.right;
    const chartHeight = height - margin.top - margin.bottom;

    return (
      <svg width={width} height={height} className="border border-gray-300 dark:border-gray-600 rounded">
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Bars */}
          {data.map((d, i) => (
            <rect
              key={i}
              x={(d.x / n) * chartWidth - 3}
              y={chartHeight - (d.y / maxY) * chartHeight}
              width={6}
              height={(d.y / maxY) * chartHeight}
              fill="rgb(239, 68, 68)"
              opacity={0.7}
            />
          ))}

          {/* X-axis */}
          <line x1={0} y1={chartHeight} x2={chartWidth} y2={chartHeight} stroke="currentColor" />

          {/* Y-axis */}
          <line x1={0} y1={0} x2={0} y2={chartHeight} stroke="currentColor" />

          {/* Axis labels */}
          <text x={chartWidth / 2} y={chartHeight + 30} textAnchor="middle" className="text-xs">k</text>
          <text x={-30} y={chartHeight / 2} textAnchor="middle" className="text-xs" transform={`rotate(-90, -30, ${chartHeight / 2})`}>P(X = k)</text>
        </g>
      </svg>
    );
  };

  // Simple SVG chart component for CDF
  const CDFChart = ({ data }) => {
    const width = 400;
    const height = 200;
    const margin = { top: 20, right: 20, bottom: 40, left: 40 };
    const chartWidth = width - margin.left - margin.right;
    const chartHeight = height - margin.top - margin.bottom;

    // Create path for step function
    let path = `M 0 ${chartHeight}`;
    data.forEach((d, i) => {
      const x = (d.x / n) * chartWidth;
      const y = chartHeight - d.y * chartHeight;
      if (i === 0) {
        path += ` L ${x} ${chartHeight} L ${x} ${y}`;
      } else {
        path += ` L ${x} ${y}`;
      }
      if (i < data.length - 1) {
        const nextX = ((d.x + 1) / n) * chartWidth;
        path += ` L ${nextX} ${y}`;
      }
    });

    return (
      <svg width={width} height={height} className="border border-gray-300 dark:border-gray-600 rounded">
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* CDF line */}
          <path d={path} fill="none" stroke="rgb(34, 197, 94)" strokeWidth={2} />

          {/* Points */}
          {data.map((d, i) => (
            <circle
              key={i}
              cx={(d.x / n) * chartWidth}
              cy={chartHeight - d.y * chartHeight}
              r={2}
              fill="rgb(34, 197, 94)"
            />
          ))}

          {/* X-axis */}
          <line x1={0} y1={chartHeight} x2={chartWidth} y2={chartHeight} stroke="currentColor" />

          {/* Y-axis */}
          <line x1={0} y1={0} x2={0} y2={chartHeight} stroke="currentColor" />

          {/* Axis labels */}
          <text x={chartWidth / 2} y={chartHeight + 30} textAnchor="middle" className="text-xs">k</text>
          <text x={-30} y={chartHeight / 2} textAnchor="middle" className="text-xs" transform={`rotate(-90, -30, ${chartHeight / 2})`}>P(X ≤ k)</text>
        </g>
      </svg>
    );
  };

  return (
    <div className="space-y-8 max-w-6xl mx-auto pb-12">
      {/* Header */}
      <div className="text-center space-y-4">
        <div className="flex items-center justify-center space-x-3">
          <Calculator className="w-8 h-8 text-red-600" />
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Binomial Distribution
          </h1>
        </div>
        <p className="text-gray-600 dark:text-gray-300 max-w-2xl mx-auto">
          Analyze the binomial distribution with comprehensive calculations, visualizations, and statistical insights.
        </p>
      </div>

      {/* Parameters and Statistics Side by Side */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Parameter Input Section */}
        <div className="bg-white/10 dark:bg-gray-800/50 backdrop-blur-sm rounded-lg shadow-lg p-6 border border-white/20 dark:border-gray-700/50">
          <h2 className="text-xl font-semibold mb-4 text-gray-900 dark:text-white">Parameters</h2>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                n (Number of trials)
              </label>
              <input
                type="number"
                min="1"
                max="100"
                value={n}
                onChange={(e) => handleNChange(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md
                         focus:ring-red-500 focus:border-red-500 dark:bg-gray-700 dark:text-white"
              />
              <p className="text-xs text-gray-500 mt-1">Range: 1-100</p>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                p (Probability of success)
              </label>
              <input
                type="number"
                min="0"
                max="1"
                step="0.001"
                value={p}
                onChange={(e) => handlePChange(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md
                         focus:ring-red-500 focus:border-red-500 dark:bg-gray-700 dark:text-white"
              />
              <p className="text-xs text-gray-500 mt-1">Range: 0-1</p>
            </div>
          </div>

          {/* Variable Explanations */}
          <div className="mt-6 p-4 bg-blue-50/80 dark:bg-blue-900/30 rounded-lg border border-blue-200/50 dark:border-blue-700/50">
            <h3 className="font-semibold text-blue-900 dark:text-blue-100 mb-2">Variable Definitions</h3>
            <div className="space-y-2 text-sm text-blue-800 dark:text-blue-200">
              <div><strong>n:</strong> Number of independent trials</div>
              <div><strong>p:</strong> Probability of success on each trial</div>
              <div><strong>q:</strong> Probability of failure (q = 1 - p)</div>
              <div><strong>X:</strong> Random variable (number of successes)</div>
            </div>
          </div>
        </div>

        {/* Calculated Statistics */}
        <div className="bg-white/10 dark:bg-gray-800/50 backdrop-blur-sm rounded-lg shadow-lg p-6 border border-white/20 dark:border-gray-700/50">
          <h2 className="text-xl font-semibold mb-4 text-gray-900 dark:text-white">Calculated Statistics</h2>

          <div className="grid grid-cols-2 gap-4">
            <div className="text-center p-4 bg-gray-50/80 dark:bg-gray-700/80 rounded-lg border border-gray-200/50 dark:border-gray-600/50">
              <div className="text-2xl font-bold text-red-600">{statistics.q.toFixed(4)}</div>
              <div className="text-sm text-gray-600 dark:text-gray-300">q</div>
            </div>
            <div className="text-center p-4 bg-gray-50/80 dark:bg-gray-700/80 rounded-lg border border-gray-200/50 dark:border-gray-600/50">
              <div className="text-2xl font-bold text-red-600">{statistics.mean.toFixed(4)}</div>
              <div className="text-sm text-gray-600 dark:text-gray-300">Mean (μ)</div>
            </div>
            <div className="text-center p-4 bg-gray-50/80 dark:bg-gray-700/80 rounded-lg border border-gray-200/50 dark:border-gray-600/50">
              <div className="text-2xl font-bold text-red-600">{statistics.variance.toFixed(4)}</div>
              <div className="text-sm text-gray-600 dark:text-gray-300">Variance (σ²)</div>
            </div>
            <div className="text-center p-4 bg-gray-50/80 dark:bg-gray-700/80 rounded-lg border border-gray-200/50 dark:border-gray-600/50">
              <div className="text-2xl font-bold text-red-600">{statistics.stdDev.toFixed(4)}</div>
              <div className="text-sm text-gray-600 dark:text-gray-300">Std Dev (σ)</div>
            </div>
          </div>

          <div className="mt-4">
            <div className="text-center p-4 bg-gray-50/80 dark:bg-gray-700/80 rounded-lg border border-gray-200/50 dark:border-gray-600/50">
              <div className="text-2xl font-bold text-red-600">{statistics.skew.toFixed(4)}</div>
              <div className="text-sm text-gray-600 dark:text-gray-300">Skewness</div>
            </div>
          </div>
        </div>
      </div>

      {/* Visualizations */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* PDF Chart */}
        <div className="bg-white/10 dark:bg-gray-800/50 backdrop-blur-sm rounded-lg shadow-lg p-6 border border-white/20 dark:border-gray-700/50">
          <div className="flex items-center space-x-2 mb-4">
            <BarChart3 className="w-5 h-5 text-red-600" />
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              Probability Mass Function (PDF)
            </h3>
          </div>
          <div className="flex justify-center">
            <PDFChart data={chartData.pdfData} />
          </div>
        </div>

        {/* CDF Chart */}
        <div className="bg-white/10 dark:bg-gray-800/50 backdrop-blur-sm rounded-lg shadow-lg p-6 border border-white/20 dark:border-gray-700/50">
          <div className="flex items-center space-x-2 mb-4">
            <TrendingUp className="w-5 h-5 text-green-600" />
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              Cumulative Distribution Function (CDF)
            </h3>
          </div>
          <div className="flex justify-center">
            <CDFChart data={chartData.cdfData} />
          </div>
        </div>
      </div>

      {/* Outcomes Table */}
      <div className="bg-white/10 dark:bg-gray-800/50 backdrop-blur-sm rounded-lg shadow-lg p-6 border border-white/20 dark:border-gray-700/50">
        <div className="flex items-center space-x-2 mb-4">
          <Table className="w-5 h-5 text-blue-600" />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            Discrete Outcomes Table
          </h3>
        </div>

        <div className="overflow-x-auto max-h-96">
          <table className="w-full text-sm">
            <thead className="bg-gray-50/80 dark:bg-gray-700/80 sticky top-0 border-b border-gray-200/50 dark:border-gray-600/50">
              <tr>
                <th className="px-4 py-2 text-left font-medium text-gray-900 dark:text-white">k</th>
                <th className="px-4 py-2 text-left font-medium text-gray-900 dark:text-white">P(X = k)</th>
                <th className="px-4 py-2 text-left font-medium text-gray-900 dark:text-white">P(X = k) %</th>
                <th className="px-4 py-2 text-left font-medium text-gray-900 dark:text-white">P(X ≤ k)</th>
                <th className="px-4 py-2 text-left font-medium text-gray-900 dark:text-white">P(X ≤ k) %</th>
              </tr>
            </thead>
            <tbody>
              {outcomeTable.map((row, index) => (
                <tr key={row.k} className={index % 2 === 0 ? 'bg-gray-50/40 dark:bg-gray-700/40' : 'bg-transparent'}>
                  <td className="px-4 py-2 font-medium">{row.k}</td>
                  <td className="px-4 py-2">{row.probability.toFixed(6)}</td>
                  <td className="px-4 py-2">{row.percentage}%</td>
                  <td className="px-4 py-2">{row.cumulative.toFixed(6)}</td>
                  <td className="px-4 py-2">{row.cumulativePercentage}%</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Formulas Section */}
      <div className="bg-white/10 dark:bg-gray-800/50 backdrop-blur-sm rounded-lg shadow-lg p-6 border border-white/20 dark:border-gray-700/50">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center space-x-2">
            <Info className="w-5 h-5 text-purple-600" />
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
              Mathematical Formulas
            </h3>
          </div>
          <button
            onClick={() => setShowFormulas(!showFormulas)}
            className="px-3 py-1 text-sm bg-purple-100/80 dark:bg-purple-900/40 text-purple-700 dark:text-purple-300 rounded-md hover:bg-purple-200/80 dark:hover:bg-purple-900/60 transition-colors border border-purple-200/50 dark:border-purple-700/50"
          >
            {showFormulas ? 'Hide' : 'Show'} Formulas
          </button>
        </div>

        {showFormulas && (
          <div className="space-y-6">
            {/* Basic Formulas */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h4 className="font-semibold text-gray-900 dark:text-white mb-2">Probability Mass Function (PDF)</h4>
                <div className="bg-gray-50/80 dark:bg-gray-700/80 p-4 rounded-lg font-mono text-sm border border-gray-200/50 dark:border-gray-600/50">
                  P(X = k) = C(n,k) × p^k × (1-p)^(n-k)
                  <br />
                  <span className="text-gray-600 dark:text-gray-400">where C(n,k) = n! / (k!(n-k)!)</span>
                </div>
              </div>

              <div>
                <h4 className="font-semibold text-gray-900 dark:text-white mb-2">Cumulative Distribution Function (CDF)</h4>
                <div className="bg-gray-50/80 dark:bg-gray-700/80 p-4 rounded-lg font-mono text-sm border border-gray-200/50 dark:border-gray-600/50">
                  P(X ≤ k) = Σ(i=0 to k) C(n,i) × p^i × (1-p)^(n-i)
                </div>
              </div>

              <div>
                <h4 className="font-semibold text-gray-900 dark:text-white mb-2">Mean and Variance</h4>
                <div className="bg-gray-50/80 dark:bg-gray-700/80 p-4 rounded-lg font-mono text-sm border border-gray-200/50 dark:border-gray-600/50">
                  μ = np
                  <br />
                  σ² = np(1-p)
                  <br />
                  σ = √(np(1-p))
                </div>
              </div>

              <div>
                <h4 className="font-semibold text-gray-900 dark:text-white mb-2">Skewness</h4>
                <div className="bg-gray-50/80 dark:bg-gray-700/80 p-4 rounded-lg font-mono text-sm border border-gray-200/50 dark:border-gray-600/50">
                  Skew = (q - p) / σ
                  <br />
                  <span className="text-gray-600 dark:text-gray-400">where q = 1 - p</span>
                </div>
              </div>
            </div>

            {/* Advanced Mathematical Relationships */}
            <div>
              <div className="flex items-center justify-between mb-4">
                <h4 className="font-semibold text-gray-900 dark:text-white">Advanced Mathematical Relationships</h4>
                <button
                  onClick={() => setShowAdvancedMath(!showAdvancedMath)}
                  className="px-3 py-1 text-sm bg-indigo-100/80 dark:bg-indigo-900/40 text-indigo-700 dark:text-indigo-300 rounded-md hover:bg-indigo-200/80 dark:hover:bg-indigo-900/60 transition-colors border border-indigo-200/50 dark:border-indigo-700/50"
                >
                  {showAdvancedMath ? 'Hide' : 'Show'} Advanced Math
                </button>
              </div>

              {showAdvancedMath && (
                <div className="space-y-4">
                  <div className="bg-indigo-50/80 dark:bg-indigo-900/30 p-4 rounded-lg border border-indigo-200/50 dark:border-indigo-700/50">
                    <h5 className="font-semibold text-indigo-900 dark:text-indigo-100 mb-2">
                      Regularized Incomplete Beta Function
                    </h5>
                    <div className="font-mono text-sm text-indigo-800 dark:text-indigo-200">
                      P(X ≤ k) = I<sub>1-p</sub>(n-k, k+1)
                      <br />
                      <span className="text-indigo-600 dark:text-indigo-300">
                        where I<sub>x</sub>(a,b) is the regularized incomplete beta function
                      </span>
                    </div>
                  </div>

                  <div className="bg-indigo-50/80 dark:bg-indigo-900/30 p-4 rounded-lg border border-indigo-200/50 dark:border-indigo-700/50">
                    <h5 className="font-semibold text-indigo-900 dark:text-indigo-100 mb-2">
                      Relationship to Beta Distribution
                    </h5>
                    <div className="font-mono text-sm text-indigo-800 dark:text-indigo-200">
                      If Y ~ Beta(k+1, n-k), then P(X ≤ k) = P(Y ≤ 1-p)
                      <br />
                      <span className="text-indigo-600 dark:text-indigo-300">
                        The binomial CDF equals the beta distribution CDF
                      </span>
                    </div>
                  </div>

                  <div className="bg-indigo-50/80 dark:bg-indigo-900/30 p-4 rounded-lg border border-indigo-200/50 dark:border-indigo-700/50">
                    <h5 className="font-semibold text-indigo-900 dark:text-indigo-100 mb-2">
                      Relationship to F-Distribution
                    </h5>
                    <div className="font-mono text-sm text-indigo-800 dark:text-indigo-200">
                      P(X ≤ k) = P(F ≤ f) where F ~ F(2(n-k), 2(k+1))
                      <br />
                      <span className="text-indigo-600 dark:text-indigo-300">
                        and f = (n-k)(1-p) / ((k+1)p)
                      </span>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default BinomialTab;
